SELECT EXISTS (
SELECT 1
FROM anonymous_players
WHERE id = #{playerId}
)

SELECT EXISTS (
SELECT 1
FROM cases
WHERE id = #{caseId}
)

SELECT EXISTS (
SELECT 1
FROM game_sessions
WHERE player_id = #{playerId}
AND case_id = #{caseId}
)

SELECT EXISTS (
SELECT 1
FROM game_sessions
WHERE id = #{sessionId}
)
